#include <stdio.h>
#include <stdlib.h>

int racecar(int target) {
    int *dp = (int*)calloc((size_t)target + 1, sizeof(int));
    for (int i = 1; i <= target; ++i) {
        int k = 0, p = 1;
        while (p < i + 1) { p <<= 1; ++k; }
        if (i == p - 1) { dp[i] = k; continue; }
        dp[i] = k + 1 + dp[p - 1 - i];
        for (int j = 0; j < k - 1; ++j) {
            int remaining = i - (p >> 1) + (1 << j);
            int cand = k + j + 1 + dp[remaining];
            if (cand < dp[i]) dp[i] = cand;
        }
    }
    int ans = dp[target]; free(dp); return ans;
}

