class Solution {
public:
    int racecar(int target) {
        vector<int> dp(target + 1, 0);
        for (int i = 1; i <= target; ++i) {
            int k = 0;
            while ((1 << k) - 1 < i) ++k;
            if (i == (1 << k) - 1) { dp[i] = k; continue; }
            dp[i] = k + 1 + dp[(1 << k) - 1 - i];
            for (int j = 0; j < k - 1; ++j) {
                int remaining = i - (1 << (k - 1)) + (1 << j);
                dp[i] = min(dp[i], k + j + 1 + dp[remaining]);
            }
        }
        return dp[target];
    }
};

