            k = i.bit_length()
            if i == (1 << k) - 1:
                dp[i] = k
                continue
            dp[i] = k + 1 + dp[(1 << k) - 1 - i]
            for j in range(k - 1):
                remaining = i - (1 << (k - 1)) + (1 << j)
                dp[i] = min(dp[i], k + j + 1 + dp[remaining])
